import React, { useState } from "react";
import { BrowserRouter, Routes, Route, NavLink } from "react-router-dom";
import ContactsPage from "./containers/contactsPage/ContactsPage";
import AppointmentsPage from "./containers/appointmentsPage/AppointmentsPage";

function App() {
  // State for contacts and appointments (each an array of objects)
  const [contacts, setContacts] = useState([]);
  const [appointments, setAppointments] = useState([]);

  // Callback to add a new contact
  // Receives a name, phone, and email and adds a new contact object
  const addContact = (name, phone, email) => {
    setContacts((prevContacts) => [
      ...prevContacts,
      { name, phone, email }
    ]);
  };

  // Callback to add a new appointment
  // Receives a title, contact, date, and time and adds a new appointment object
  const addAppointment = (title, contact, date, time) => {
    setAppointments((prevAppointments) => [
      ...prevAppointments,
      { title, contact, date, time }
    ]);
  };

  return (
    <BrowserRouter>
      {/* Navigation links between Contacts and Appointments pages */}
      <nav>
        <NavLink to="/">Contacts</NavLink>
        <NavLink to="/appointments">Appointments</NavLink>
      </nav>
      <Routes>
        {/* Pass contacts array and addContact callback to ContactsPage */}
        <Route
          path="/"
          element={<ContactsPage contacts={contacts} addContact={addContact} />}
        />
        {/* Pass appointments array, contacts array, and addAppointment callback to AppointmentsPage */}
        <Route
          path="/appointments"
          element={
            <AppointmentsPage
              appointments={appointments}
              contacts={contacts}
              addAppointment={addAppointment}
            />
          }
        />
      </Routes>
    </BrowserRouter>
  );
}

export default App;
